describe('Notification Auto-Dismiss Feature', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should auto-dismiss notifications after 5 seconds', () => {
    // Intercept the notification API call
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-title"]').should('contain', 'New message');
    cy.get('[data-testid="notification-body"]').should('contain', 'John Doe');

    // Wait for 5 seconds
    cy.wait(5000);

    // Verify notification is no longer visible
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify notification count is decremented
    cy.get('[data-testid="notification-count"]').should('contain', '1');
  });

  it('should not auto-dismiss notifications when dismissed manually', () => {
    // Intercept the notification API call
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-title"]').should('contain', 'New message');

    // Manually dismiss notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify notification is still visible after manual dismissal
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Verify notification count is decremented
    cy.get('[data-testid="notification-count"]').should('contain', '0');
  });
});
